public class Solution{public int MyAtoi(string s){int i=0,sign=1,r=0;while(i<s.Length&&s[i]==' ')i++;if(i<s.Length&&(s[i]=='+'||s[i]=='-')){if(s[i++]=='-')sign=-1;}while(i<s.Length&&char.IsDigit(s[i])){int d=s[i++]-'0';if(sign>0){if(r>int.MaxValue/10||(r==int.MaxValue/10&&d>7))return int.MaxValue;r=r*10+d;}else{if(r<int.MinValue/10||(r==int.MinValue/10&&d>8))return int.MinValue;r=r*10-d;}}return r;}}
